application.css:
* { box-sizing: border-box; }

:root {
  color: #172033;
  background: #f4f7fb;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.5;
}

body { margin: 0; }
.container { width: min(100% - 2rem, 900px); margin: 0 auto; }
.site-header { background: #173b65; color: #fff; padding: 2.25rem 0; }
h1, h2 { line-height: 1.2; }
h1 { margin: 0 0 .5rem; font-size: clamp(1.8rem, 5vw, 2.6rem); }
h2 { margin-top: 0; color: #173b65; }
main { display: grid; gap: 1.5rem; padding: 2rem 0 3rem; }
.booking-panel, .appointments-panel { background: #fff; border: 1px solid #d5deea; border-radius: .6rem; padding: clamp(1.2rem, 4vw, 2rem); box-shadow: 0 2px 8px #17203312; }
.form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; }
.form-field-wide { grid-column: 1 / -1; }
.form-field { display: flex; flex-direction: column; gap: .35rem; }
label { font-weight: 650; }
input, select { width: 100%; min-height: 2.75rem; border: 1px solid #718096; border-radius: .35rem; padding: .55rem .7rem; color: #172033; background: #fff; font: inherit; }
input:focus, select:focus, button:focus, .form-error:focus { outline: 3px solid #f3b63f; outline-offset: 2px; }
.field-error { min-height: 1.25rem; margin: 0; color: #a12622; font-size: .9rem; }
.required-note { margin: .5rem 0; font-size: .9rem; color: #46566b; }
.form-error { color: #a12622; font-weight: 650; margin: .5rem 0 1rem; }
.primary-button, .cancel-button { border: 0; border-radius: .35rem; padding: .7rem 1rem; font: inherit; font-weight: 700; cursor: pointer; }
.primary-button { background: #176b4d; color: #fff; }
.primary-button:hover { background: #12573e; }
.confirmation { margin-top: 1rem; padding: .85rem 1rem; border-left: 4px solid #176b4d; background: #e4f4ec; color: #124b37; }
.booking-list { display: grid; gap: 1rem; }
.empty-state { color: #526176; margin: 0; }
.booking { border: 1px solid #c9d5e3; border-radius: .45rem; padding: 1rem; display: flex; justify-content: space-between; align-items: flex-start; gap: 1rem; }
.booking h3 { margin: 0 0 .35rem; color: #173b65; }
.booking p { margin: .25rem 0; }
.booking[data-status="cancelled"] { background: #f1f3f5; color: #596575; }
.booking[data-status="cancelled"] h3 { color: #596575; text-decoration: line-through; }
.cancel-button { background: #a12622; color: #fff; white-space: nowrap; }
.cancel-button:hover { background: #801d1a; }
@media (max-width: 600px) { .form-grid { grid-template-columns: 1fr; } .form-field-wide { grid-column: auto; } .booking { flex-direction: column; } }

application.javascript:
const form = document.querySelector('#booking-form');
const nameInput = document.querySelector('#booking-name');
const emailInput = document.querySelector('#booking-email');
const dateInput = document.querySelector('#booking-date');
const timeInput = document.querySelector('#booking-time');
const typeInput = document.querySelector('#booking-type');
const list = document.querySelector('#booking-list');
const confirmation = document.querySelector('#confirmation');
const formError = document.querySelector('#form-error');
let bookings = [];

function getToday() {
  const now = new Date();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return `${now.getFullYear()}-${month}-${day}`;
}

function setDateMinimum() {
  dateInput.min = getToday();
}

function clearErrors() {
  document.querySelectorAll('.field-error').forEach((error) => { error.textContent = ''; });
  formError.textContent = '';
}

function showFieldError(id, message) {
  document.querySelector(`#${id}-error`).textContent = message;
}

function validateForm() {
  clearErrors();
  let valid = true;
  if (!nameInput.value.trim()) { showFieldError('name', 'Enter the customer name.'); valid = false; }
  if (!emailInput.value.trim() || !emailInput.validity.valid) { showFieldError('email', 'Enter a valid email address.'); valid = false; }
  if (!dateInput.value) { showFieldError('date', 'Choose an appointment date.'); valid = false; }
  else if (dateInput.value < getToday()) { showFieldError('date', 'The appointment date cannot be in the past.'); valid = false; }
  if (!timeInput.value) { showFieldError('time', 'Choose an appointment time.'); valid = false; }
  if (!typeInput.value) { showFieldError('type', 'Select an appointment type.'); valid = false; }
  if (!valid) { formError.textContent = 'Please correct the highlighted fields.'; formError.focus(); }
  return valid;
}

function formatDate(date) {
  return new Date(`${date}T00:00:00`).toLocaleDateString(undefined, { dateStyle: 'long' });
}

function renderBookings() {
  list.replaceChildren();
  if (!bookings.length) {
    const empty = document.createElement('p');
    empty.className = 'empty-state';
    empty.textContent = 'No bookings yet.';
    list.append(empty);
    return;
  }
  bookings.forEach((booking) => {
    const article = document.createElement('article');
    article.className = 'booking';
    article.dataset.testid = 'booking';
    article.dataset.status = booking.cancelled ? 'cancelled' : 'active';
    const details = document.createElement('div');
    const heading = document.createElement('h3');
    heading.dataset.testid = 'booking-name-display';
    heading.textContent = booking.name;
    const info = document.createElement('p');
    info.textContent = `${booking.type} · ${formatDate(booking.date)} at ${booking.time}`;
    const email = document.createElement('p');
    email.textContent = booking.email;
    details.append(heading, info, email);
    if (booking.cancelled) {
      const status = document.createElement('p');
      status.textContent = 'Cancelled';
      details.append(status);
    } else {
      const cancel = document.createElement('button');
      cancel.type = 'button';
      cancel.className = 'cancel-button';
      cancel.dataset.testid = 'booking-cancel';
      cancel.dataset.id = booking.id;
      cancel.textContent = 'Cancel booking';
      cancel.addEventListener('click', cancelBooking);
      article.append(details, cancel);
      list.append(article);
      return;
    }
    article.append(details);
    list.append(article);
  });
}

function createBooking(event) {
  event.preventDefault();
  if (!validateForm()) return;
  bookings.push({ id: crypto.randomUUID ? crypto.randomUUID() : String(Date.now()), name: nameInput.value.trim(), email: emailInput.value.trim(), date: dateInput.value, time: timeInput.value, type: typeInput.value, cancelled: false });
  renderBookings();
  confirmation.textContent = 'Booking created successfully.';
  confirmation.hidden = false;
  form.reset();
  setDateMinimum();
  nameInput.focus();
}

function cancelBooking(event) {
  const booking = bookings.find((item) => item.id === event.currentTarget.dataset.id);
  if (booking) { booking.cancelled = true; renderBookings(); }
}

setDateMinimum();
form.addEventListener('submit', createBooking);
